// E3 auto-pausa: encaminhar fromMe com TEXTO (atendente no app).
// Nao descartar fromMe de conteudo — a Chatbot API pausa se origem_bot ausente.
// Ignorar ack/status/update/reaction e eventos sem texto (API tambem e defensiva).
const root = $input.first().json;
const b = root.body || root || {};
const data = b.data || {};
const key = data.key || {};
const event = String(b.event || root.event || '').toLowerCase();
if (event && (event.includes('messages.update') || event.includes('message.ack') || event.includes('reaction'))) return [];
const jid = String(key.remoteJid || '').trim();
const jidAlt = String(key.remoteJidAlt || '').trim();
const instance = String(b.instance || '__INSTANCE__');
const msg = data.message || {};
if (msg.reactionMessage) return [];
const texto = msg.conversation || msg.extendedTextMessage?.text || '';
const privado = jid.endsWith('@s.whatsapp.net') || jid.endsWith('@lid');
if (!privado || !jid || !texto) return [];
const jidTelefone = jidAlt.endsWith('@s.whatsapp.net') ? jidAlt : jid;
const telefone = jidTelefone.endsWith('@lid') ? jidTelefone : jidTelefone.split('@')[0];
const destino = jid.endsWith('@lid') ? jid : jid.split('@')[0];
return [{ json: {
  instance, remoteJid: jid, remoteJidAlt: jidAlt, telefone, destino, texto,
  pushName: data.pushName || '', providerMessageId: String(key.id || ''),
  fromMe: Boolean(key.fromMe)
} }];

const estado = $input.first().json || {};
const origem = $('Extrair1').first().json;
if (origem.fromMe || estado.duplicada === true || estado.bot_ativo !== true) return [];
return [{ json: origem }];

const chat = $input.first().json || {};
const origem = $('Extrair1').first().json;
// Fail closed: só responde quando a Evolution afirmar explicitamente isSaved === false.
if (chat.isSaved !== false) return [];
return [{ json: { ...origem, isSaved: false } }];

const input = typeof query === 'string' ? { termo: query } : (query || {});
const termoRaw = (input.termo ?? input.query ?? '').toString().trim();
const termo = ['', 'todos', 'tudo', 'all', '*'].includes(termoRaw.toLowerCase()) ? '' : termoRaw;
const qs = termo ? { termo } : {};
const resp = await helpers.httpRequest({
  method: 'GET',
  url: 'http://chatbot-api:8000/v1/estoque/buscar',
  qs,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? { versao_texto: query } : (query || {});
const telefone = (input.telefone || '').toString().trim();
const versao_texto = (input.versao_texto || input.texto || 'aceito').toString().trim();
if (!telefone) return JSON.stringify({ erro: 'telefone obrigatorio' });
const resp = await helpers.httpRequest({
  method: 'POST',
  url: 'http://chatbot-api:8000/v1/consentimentos',
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
  body: {
    telefone,
    versao_texto,
    finalidade: 'simulação e contato da loja',
  },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? { interesse: query } : (query || {});
const telefone = (input.telefone || '').toString().trim();
if (!telefone) return JSON.stringify({ erro: 'telefone_obrigatorio' });

const nomeRaw = (input.nome || '').toString().trim();
const nomeGenerico = !nomeRaw || ['cliente', 'customer', 'user', 'usuario'].includes(nomeRaw.toLowerCase());

const body = {
  telefone,
  interesse: (input.interesse || '').toString().trim(),
};
if (input.etapa) body.etapa = String(input.etapa).trim();
if (!nomeGenerico) body.nome = nomeRaw;

try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/leads',
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body,
    json: true,
  });
  return JSON.stringify({ ok: true, lead: resp });
} catch (e) {
  const status = e.response?.statusCode || e.statusCode || e.status || null;
  const detail = e.response?.body?.detail || e.message || String(e);
  return JSON.stringify({ ok: false, status, erro: detail });
}

const input = typeof query === 'string' ? {} : (query || {});
const telefone = (input.telefone || '').toString().trim();
const body = {
  cpf: String(input.cpf || ''),
  nascimento: String(input.nascimento || ''),
  entrada: Number(input.entrada ?? 0),
  placa: (input.placa || '').toString().trim(),
  telefone,
};

if (!telefone || !body.placa || !body.cpf || !body.nascimento) {
  return JSON.stringify({
    mensagem: 'Ainda faltam dados para solicitar a simulação.',
  });
}

try {
  const mensagemId = String($('Extrair1').first().json.providerMessageId || '').trim();
  const headers = { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' };
  if (mensagemId) headers['Idempotency-Key'] = mensagemId;
  await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/simulacoes/solicitar',
    headers,
    body,
    json: true,
    timeout: 10000,
  });
} catch (_) {
  // O vendedor assume mesmo se o serviço de simulação estiver indisponível.
}

try {
  await helpers.httpRequest({
    method: 'PATCH',
    url: `http://chatbot-api:8000/v1/conversas/${encodeURIComponent(telefone)}/estado`,
    headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
    body: { bot_ativo: false },
    json: true,
  });
} catch (_) {
  // Não expor detalhes internos ao cliente ou ao modelo.
}

return JSON.stringify({
  mensagem: 'Certo, vou preparar a simulação e chamar um vendedor para trazer o resultado para você.',
});

const input = typeof query === 'string' ? { telefone: query } : (query || {});
const telefone = (input.telefone || '').toString().trim();
if (!telefone) return JSON.stringify({ erro: 'telefone obrigatorio' });
const resp = await helpers.httpRequest({
  method: 'PATCH',
  url: `http://chatbot-api:8000/v1/conversas/${encodeURIComponent(telefone)}/estado`,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__', 'Content-Type': 'application/json' },
  body: { bot_ativo: false },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? { placa: query } : (query || {});
const placa = (input.placa || '').toString().trim();
if (!placa) return JSON.stringify({ erro: 'placa obrigatoria' });
const resp = await helpers.httpRequest({
  method: 'GET',
  url: `http://chatbot-api:8000/v1/estoque/por-placa/${encodeURIComponent(placa)}`,
  headers: { Authorization: 'Bearer __CHATBOT_TOKEN__' },
  json: true,
});
return JSON.stringify(resp);

const input = typeof query === 'string' ? {} : (query || {});
const telefone_solicitante = (input.telefone_solicitante || input.telefone || '').toString().trim();
if (!telefone_solicitante) return JSON.stringify({ erro: 'telefone_solicitante obrigatorio' });

const body = {
  telefone_solicitante,
  tipo: String(input.tipo || 'moto'),
  marca: String(input.marca || ''),
  modelo: String(input.modelo || ''),
  ano_modelo: Number(input.ano_modelo),
  preco: Number(input.preco),
  km: Number(input.km ?? 0),
  placa: String(input.placa || '').trim().toUpperCase(),
};
if (input.versao) body.versao = String(input.versao);
if (input.cor) body.cor = String(input.cor);
if (input.codigo_interno) body.codigo_interno = String(input.codigo_interno);
if (input.foto_url) body.foto_url = String(input.foto_url);

const headers = {
  Authorization: 'Bearer __CHATBOT_TOKEN__',
  'Content-Type': 'application/json',
};
if (input.idempotency_key) headers['Idempotency-Key'] = String(input.idempotency_key);

try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://chatbot-api:8000/v1/operacao/veiculos',
    headers,
    body,
    json: true,
  });
  return JSON.stringify({ ok: true, veiculo: resp });
} catch (e) {
  const status = e.response?.statusCode || e.statusCode || e.status || null;
  const detail = e.response?.body?.detail || e.message || String(e);
  return JSON.stringify({ ok: false, status, erro: detail });
}
